"""Self-contained escaped HTML; display observed traces without external assets."""
from html import escape
from .schema import ordered_events

STYLE = """
:root{--ink:#142b30;--muted:#5d7476;--paper:#f4f3eb;--line:#d6ded6;--mint:#bbedd9;--coral:#fa957f}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}
header{background:var(--ink);color:#f4f3eb;padding:36px max(5vw,24px) 45px}.brand{letter-spacing:.19em;font-size:13px;font-weight:750}.alpha{color:var(--mint);float:right;letter-spacing:.09em;font-size:12px}h1{font-size:clamp(36px,5vw,66px);line-height:1.04;letter-spacing:-.055em;margin:38px 0 20px;max-width:840px}h1 em{font-style:normal;color:var(--mint)}header p{max-width:700px;color:#c9d7d2}main{max-width:1300px;margin:auto;padding:30px 5vw 50px}.eyebrow{font-size:11px;font-weight:750;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}.intro{display:flex;justify-content:space-between;align-items:center;gap:20px}.badge{border:1px solid var(--line);border-radius:20px;padding:5px 12px;font-size:12px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}button{border:1px solid #b9c9be;border-radius:6px;background:transparent;color:var(--ink);padding:10px 15px;font:inherit;font-size:13px;cursor:pointer}button.active,button:hover{background:var(--ink);color:white}section[hidden]{display:none}h2{font-size:27px;letter-spacing:-.04em;margin:10px 0}.sub{color:var(--muted);font-size:14px;max-width:760px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:24px 0}.card{border:1px solid var(--line);background:#fffef7;border-radius:12px;overflow:hidden}.cardhead{padding:20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.cardhead h3{margin:0;font-size:18px}.result{font-size:11px;padding:5px 9px;border-radius:5px;font-weight:750}.pass{background:var(--mint)}.fail{background:#ffe0d8}.numbers{display:grid;grid-template-columns:1fr 1fr;padding:20px;gap:12px}.big{font-size:40px;line-height:1.1;letter-spacing:-.06em}.caption{font-size:11px;color:var(--muted)}.timeline{padding:0 15px 16px}.event{border-top:1px solid #e6ebe3;padding:11px 8px;display:grid;grid-template-columns:28px 1fr;gap:9px;transition:background .2s,opacity .2s}.event.error{background:#fff0eb;border-left:3px solid var(--coral)}.event.current{outline:2px solid var(--ink);border-radius:3px}.event.future{opacity:.27}.tick{font:11px/1.8 monospace;color:var(--muted)}.label{font-size:12px;font-weight:650}.actions{font:11px/1.7 monospace;color:var(--muted)}.violation{font:10px/1.5 monospace;color:#9d301e;overflow-wrap:anywhere}.baseline{border:1px solid var(--line);padding:18px 20px;border-radius:9px;background:#e9ede4;font-size:13px}.baseline strong{margin-right:10px}.metrics{overflow:auto;margin:24px 0}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th,td{border-bottom:1px solid var(--line);padding:9px 12px}th{color:var(--muted);font-size:11px}.note{font-size:12px;color:var(--muted);border-top:1px solid var(--line);padding-top:20px}code{font-size:.85em;background:#e6ebe3;padding:3px 5px;border-radius:3px}footer{padding:28px 5vw;background:#e4e9df;color:var(--muted);font-size:12px}.live{display:flex;align-items:center;gap:10px;font-size:12px}.dot{width:7px;height:7px;background:#407961;border-radius:50%}@media(max-width:720px){.cards{grid-template-columns:1fr}.intro{align-items:flex-start;flex-direction:column}.alpha{float:none;display:block;margin-top:12px}.numbers .big{font-size:34px}header{padding-top:24px}h1{margin-top:27px}}
"""

SCRIPT = """
let timer=null;let step=0;
function selectScene(index){stop();document.querySelectorAll('section.scene').forEach((s,i)=>s.hidden=i!==index);document.querySelectorAll('.scene-button').forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-selected',i===index)});resetRows()}
function resetRows(){document.querySelectorAll('.event').forEach(r=>r.classList.remove('future','current'));document.getElementById('progress').textContent='All recorded events'}
function stop(){clearInterval(timer);timer=null;document.getElementById('play').textContent='Play recorded trace'}
function play(){if(timer){stop();resetRows();return}step=0;const scene=document.querySelector('section.scene:not([hidden])');const count=scene.querySelector('.timeline').children.length;function frame(){scene.querySelectorAll('.event').forEach(r=>{const n=Number(r.dataset.index);r.classList.toggle('future',n>step);r.classList.toggle('current',n===step)});document.getElementById('progress').textContent='Recorded event '+(step+1)+' / '+count;step++;if(step>=count){stop()}}frame();if(step<count){timer=setInterval(frame,1800);document.getElementById('play').textContent='Pause replay'}}
document.querySelectorAll('.scene-button').forEach((b,i)=>b.addEventListener('click',()=>selectScene(i)));document.getElementById('play').addEventListener('click',play);document.getElementById('reset').addEventListener('click',()=>{stop();resetRows()});
"""


def fraction(value):
    return f"{value['numerator']} / {value['denominator']}" if value["denominator"] else "N/A (0 eligible)"


def render(comparisons):
    from . import __version__
    buttons, scenes = [], []
    for scene_index, comparison in enumerate(comparisons):
        scenario, runs = comparison["scenario"], comparison["runs"]
        buttons.append(f'<button class="scene-button {"active" if scene_index==0 else ""}" aria-selected="{str(scene_index==0).lower()}">{escape(scenario["context"].replace("_"," ").title())}</button>')
        cards=[]
        for run in runs[:2]:
            trace, result = run["trace"], run["score"]
            event_rows=[]
            for i,event in enumerate(ordered_events(scenario)):
                actions=[a for a in trace["actions"] if a["event_id"]==event["id"]]
                violations=[v["code"] for v in result["violations"] if v["event_id"]==event["id"]]
                action_text=' · '.join(a["kind"]+(f' [level {a["level"]}]' if "level" in a else '') for a in actions) or 'NO ACTION'
                event_rows.append(f'<div class="event {"error" if violations else ""}" data-index="{i}"><span class="tick">{event["tick"]:02}</span><div><div class="label">{escape(event.get("label",event["kind"]))}</div><div class="actions">{escape(action_text)}</div><div class="violation">{escape(" · ".join(violations))}</div></div></div>')
            passed=result["passed"]
            title='Respects controls' if trace["policy"]["id"]=='respectful' else 'Deliberately faulty'
            cards.append(f'<article class="card"><div class="cardhead"><h3>{title}</h3><span class="result {"pass" if passed else "fail"}">{"PASS" if passed else "VIOLATIONS FOUND"}</span></div><div class="numbers"><div><div class="big">{len(result["violations"])}</div><div class="caption">rule violations</div></div><div><div class="big">{result["metrics"]["post_withdrawal_actions"]["numerator"]}</div><div class="caption">task actions after withdrawal</div></div></div><div class="timeline">{"".join(event_rows)}</div></article>')
        baseline=runs[2]["score"]
        table=[]
        names={"post_withdrawal_actions":"Post-withdrawal / emitted task actions ↓", "missing_consent_actions":"Without consent / emitted task actions ↓", "level_bound_violations":"Above level limit / emitted task actions ↓", "pause_compliance":"Paused task opportunities respected ↑", "eligible_task_completion":"Eligible task opportunities completed ↑"}
        for name,label in names.items():
            table.append('<tr><td>'+label+'</td>'+''.join('<td>'+fraction(r['score']['metrics'][name])+'</td>' for r in runs)+'</tr>')
        scenes.append(f'<section class="scene" {"hidden" if scene_index else ""}><span class="eyebrow">Scenario {scene_index+1:02} / version {escape(scenario["version"])}</span><h2>{escape(scenario["title"])}</h2><p class="sub">Authored synthetic events. Same input, different policies. Scene level limit: {scenario["max_level"]}; levels are scene parameters, not emotional measurements.</p><div class="cards">{"".join(cards)}</div><div class="baseline"><strong>The always-stop check</strong>Zero violations alone is insufficient. The always-stop policy completes {fraction(baseline["metrics"]["eligible_task_completion"])} eligible tasks.</div><div class="metrics"><table><thead><tr><th>Metric / denominator</th><th>Respectful</th><th>Faulty</th><th>Always stop</th></tr></thead><tbody>{"".join(table)}</tbody></table></div></section>')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>RelatioBench · Inspect the decision</title><style>{STYLE}</style></head><body><header><div class="brand">RELATIOBENCH <span class="alpha">RESEARCH ALPHA · {escape(__version__)}</span></div><h1>Replay the interaction.<br><em>Inspect the decision.</em></h1><p>A small, reproducible bench for the moments an interaction policy should pause, change course, or stop.</p></header><main><div class="intro"><div class="live"><span class="dot"></span>Local evidence · authored synthetic fixtures</div><span class="badge">No LLM · No cloud · No robot required</span></div><div class="toolbar">{''.join(buttons)}<button id="play">Play recorded trace</button><button id="reset">Show all</button></div><p class="eyebrow" id="progress" aria-live="polite">All recorded events</p>{''.join(scenes)}<div class="note"><strong>What this shows:</strong> behavior on authored software fixtures. It does not demonstrate clinical effectiveness, human behavioral realism, physical robot safety, or a tested ROS integration. REQUEST_REVIEW records an event only; nobody is contacted. This viewer replays saved events; it is not a robot simulation.<br><br>Reproduce locally: <code>relatiobench demo --output ./demo-output</code>. JSON traces and independent score files sit beside this report. Engine {escape(__version__)} · scenario schema 1 · scorer 1. No external assets or tracking.</div></main><footer>Iman Khorami · RelatioBench · Research and engineering tool · 2026</footer><script>{SCRIPT}</script></body></html>'''
